window.docContents[162].resolve({"/Elementary-Functions/___4___45-Methods-of-Computation/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___45-Methods-of-Computation--___4___45-Methods-of-Computation--Real-variables___-inverse-trigonometric-functions":{"contents":"The corrected arctangent recurrence avoids cancellation; the large-argument\nseries is summed with its first term exactly once and is used only in its\nconvergent regime. The worked decimal values below are enclosures, not exact\ndecimal identities.\nDLMF 4.45.E8\n2\\arctan\\left(\\frac{x}{1+\\sqrt{1+x^2}}\\right)=\\arctan x,\\qquad 0<x<\\infty.DLMF 4.45.E9\nx_n=\\frac{x_{n-1}}{1+\\sqrt{1+x_{n-1}^2}},\\qquad n=1,2,\\ldots.DLMF 4.45.E10\n\\arctan x=2^n\\arctan x_n.DLMF 4.45.E11\n\\arctan x=\\frac{\\pi}{2}-\\frac{1}{x}+\\frac{1}{3x^3}-\\frac{1}{5x^5}+\\cdots,\\qquad x>1.DLMF 4.45.E12\nx=9.47376,\\qquad x_1\\approx0.90000,\\quad x_2\\approx0.38373,\\quad x_3\\approx0.18528,\\quad x_4\\approx0.09185.DLMF 4.45.E13\n\\arctan(9.47376)=16\\arctan x_4=1.46563\\ldots.DLMF 4.45.E14\n\\arctan x=1.57079\\ldots-0.10555\\ldots+0.00039\\ldots-\\cdots=1.46563\\ldots.\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.45 Methods of Computation\u0009§4.45 Methods of Computation","header":"Real variables: inverse trigonometric functions","id":"/Elementary-Functions/___4___45-Methods-of-Computation/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___45-Methods-of-Computation--___4___45-Methods-of-Computation--Real-variables___-inverse-trigonometric-functions"}});